<script lang="ts">
	import { enhance } from '$app/forms';
	import { goto } from '$app/navigation';
	import type { SubmitFunction } from '@sveltejs/kit';
	import { toast } from 'svelte-sonner';
	import type { PageProps } from './$types';
	import { Badge, Breadcrumb, Button, Card, ConfirmationDialog, Icon, i18n, tienePermiso } from '$lib';
	import * as DropdownMenu from '$lib/components/ui/dropdown-menu/index.js';

	let { data }: PageProps = $props();
	type Pet = (typeof data.mascotas)[number];
	let target = $state<Pet | null>(null);
	let deleteOpen = $state(false);
	let processing = $state(false);
	let deleteForm: HTMLFormElement;
	let resolveDelete: (() => void) | null = null;
	const canCreate = $derived(tienePermiso(data.usuario.permisos, 'clinic.pets.create'));
	const canUpdate = $derived(tienePermiso(data.usuario.permisos, 'clinic.pets.update'));
	const canDelete = $derived(tienePermiso(data.usuario.permisos, 'clinic.pets.delete'));
	const breadcrumbs = $derived([{ label: i18n.t('nav.dashboard'), href: '/dashboard' }, { label: i18n.t('pets.title') }]);

	function requestDelete(): Promise<void> { if (!target) return Promise.reject(new Error('invalid-pet')); return new Promise((resolve) => { resolveDelete = resolve; deleteForm.requestSubmit(); }); }
	const remove: SubmitFunction = () => { processing = true; return async ({ result, update }) => { if (result.type === 'success') { await update({ invalidateAll: true, reset: false }); toast.success(i18n.t('pets.deleted')); resolveDelete?.(); } else toast.error(i18n.t(result.type === 'failure' && typeof result.data?.petMessage === 'string' ? result.data.petMessage : 'pets.deleteError')); processing = false; resolveDelete = null; }; };
</script>

<svelte:head><title>{i18n.t('pets.title')} · Sumaq System</title></svelte:head>
<Breadcrumb items={breadcrumbs} />
<section class="flex flex-col gap-6">
	<div class="flex items-end justify-between gap-5 max-sm:flex-col max-sm:items-start"><div><h1 class="text-[28px] tracking-[-0.02em] text-ink">{i18n.t('pets.title')}</h1><p class="mt-1.5 max-w-[62ch] text-steel">{i18n.t('pets.description')}</p></div>{#if canCreate}<Button href="/clinic/pets/new"><Icon name="plus" size={18} />{i18n.t('pets.new')}</Button>{/if}</div>
	<div class="flex items-end justify-between gap-4 max-sm:flex-col max-sm:items-stretch"><form method="GET" class="flex w-full max-w-md gap-2"><label class="sr-only" for="pet-search">{i18n.t('pets.search')}</label><div class="relative flex-1"><span class="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-steel"><Icon name="search" size={17} /></span><input id="pet-search" name="q" value={data.q} maxlength="120" placeholder={i18n.t('pets.searchPlaceholder')} class="h-10 w-full rounded-md border border-hairline-strong bg-canvas pl-10 pr-3 text-sm text-ink outline-none focus:border-primary focus:ring-[3px] focus:ring-primary/20" /></div><Button type="submit" variant="utility">{i18n.t('pets.search')}</Button></form><Badge variant="outline-sky">{i18n.t('pets.count', { count: data.total })}</Badge></div>
	<Card padding="none" class="overflow-hidden">
		{#if data.mascotas.length === 0}<div class="flex flex-col items-center px-4 py-16 text-center"><span class="mb-4 grid size-12 place-items-center rounded-full bg-primary-soft text-primary"><Icon name="paw-print" size={25} /></span><h2 class="text-lg text-ink">{i18n.t(data.q ? 'pets.noResults' : 'pets.emptyTitle')}</h2><p class="mt-1 text-sm text-steel">{i18n.t(data.q ? 'pets.noResultsHelp' : 'pets.emptyDescription')}</p>{#if canCreate && !data.q}<Button href="/clinic/pets/new" class="mt-5"><Icon name="plus" size={17} />{i18n.t('pets.new')}</Button>{/if}</div>
		{:else}
			<div class="hidden overflow-x-auto md:block"><table class="w-full min-w-[820px] border-collapse text-left"><thead class="bg-surface/70"><tr class="border-b border-hairline text-[11px] font-semibold uppercase tracking-[0.05em] text-stone"><th class="px-5 py-3.5">{i18n.t('pets.pet')}</th><th class="px-4 py-3.5">{i18n.t('pets.ownerColumn')}</th><th class="px-4 py-3.5">{i18n.t('pets.profile')}</th>{#if canUpdate || canDelete}<th class="px-5 py-3.5 text-right">{i18n.t('pets.actions')}</th>{/if}</tr></thead><tbody class="divide-y divide-hairline">{#each data.mascotas as pet (pet.id_mascotas)}<tr class="transition-colors hover:bg-surface/55"><td class="px-5 py-4"><div class="flex min-w-0 items-center gap-3">{#if pet.foto_version}<img src={`/media/pets/${pet.id_mascotas}/${pet.foto_version}`} alt="" title={pet.temperamento?.etiqueta} class="size-11 shrink-0 rounded-lg border-[3px] border-hairline object-cover" style:border-color={pet.temperamento?.color_hex ?? undefined} />{:else}<span class="grid size-11 shrink-0 place-items-center rounded-lg border border-hairline bg-surface text-stone"><Icon name="paw-print" size={20} /></span>{/if}<div class="min-w-0"><strong class="block truncate text-sm text-ink">{pet.nombre}</strong><p class="mt-1 text-xs text-steel">{pet.especie.nombre}{#if pet.subespecie} · {pet.subespecie.nombre}{/if}</p>{#if pet.codigo_chip}<p class="mt-0.5 text-xs text-stone">{pet.codigo_chip}</p>{/if}</div></div></td><td class="px-4 py-4"><p class="text-sm text-ink">{pet.propietario?.nombre_completo ?? i18n.t('pets.noOwner')}</p>{#if pet.propietario}<p class="mt-1 text-xs text-steel">{pet.propietario.tipo_documento.etiqueta} · {pet.propietario.numero_documento}</p>{/if}</td><td class="px-4 py-4">{#if pet.temperamento}<div class="flex items-center gap-2 text-sm text-ink"><span class="size-2.5 rounded-full" style:background-color={pet.temperamento.color_hex ?? 'currentColor'}></span>{pet.temperamento.etiqueta}</div>{/if}<p class="mt-1 text-xs text-steel">{#if pet.peso}{pet.peso}{#if pet.unidad_peso} {pet.unidad_peso.codigo}{/if}{/if}{#if pet.peso && pet.talla} · {/if}{pet.talla?.etiqueta ?? (!pet.peso && !pet.temperamento ? '—' : '')}</p></td>{#if canUpdate || canDelete}<td class="px-5 py-4"><div class="flex justify-end"><DropdownMenu.Root><DropdownMenu.Trigger disabled={processing} aria-label={`${i18n.t('pets.actions')}: ${pet.nombre}`} class="grid size-8 place-items-center rounded-md text-stone hover:bg-surface hover:text-ink"><Icon name="ellipsis" size={18} /></DropdownMenu.Trigger><DropdownMenu.Content align="end" class="min-w-[160px]">{#if canUpdate}<DropdownMenu.Item onSelect={() => goto(`/clinic/pets/${pet.id_mascotas}/edit`)}><Icon name="pencil" size={15} />{i18n.t('pets.edit')}</DropdownMenu.Item>{/if}{#if canUpdate && canDelete}<DropdownMenu.Separator />{/if}{#if canDelete}<DropdownMenu.Item class="text-error focus:bg-error/10 focus:text-error" onSelect={() => { target = pet; deleteOpen = true; }}><Icon name="trash-2" size={15} />{i18n.t('pets.delete')}</DropdownMenu.Item>{/if}</DropdownMenu.Content></DropdownMenu.Root></div></td>{/if}</tr>{/each}</tbody></table></div>
			<div class="divide-y divide-hairline md:hidden">{#each data.mascotas as pet (pet.id_mascotas)}<article class="p-4"><div class="flex gap-3">{#if pet.foto_version}<img src={`/media/pets/${pet.id_mascotas}/${pet.foto_version}`} alt="" title={pet.temperamento?.etiqueta} class="size-12 shrink-0 rounded-lg border-[3px] border-hairline object-cover" style:border-color={pet.temperamento?.color_hex ?? undefined} />{:else}<span class="grid size-12 shrink-0 place-items-center rounded-lg border border-hairline bg-surface text-stone"><Icon name="paw-print" size={21} /></span>{/if}<div class="min-w-0 flex-1"><strong class="block truncate text-sm text-ink">{pet.nombre}</strong><p class="mt-1 truncate text-xs text-steel">{pet.especie.nombre}{#if pet.subespecie} · {pet.subespecie.nombre}{/if}</p><p class="mt-2 truncate text-sm text-ink">{pet.propietario?.nombre_completo ?? i18n.t('pets.noOwner')}</p>{#if pet.temperamento || pet.peso}<div class="mt-1 flex items-center gap-2 text-xs text-steel">{#if pet.temperamento}<span class="size-2 rounded-full" style:background-color={pet.temperamento.color_hex ?? 'currentColor'}></span>{pet.temperamento.etiqueta}{/if}{#if pet.temperamento && pet.peso} · {/if}{#if pet.peso}{pet.peso}{#if pet.unidad_peso} {pet.unidad_peso.codigo}{/if}{/if}</div>{/if}</div>{#if canUpdate || canDelete}<DropdownMenu.Root><DropdownMenu.Trigger aria-label={`${i18n.t('pets.actions')}: ${pet.nombre}`} class="grid size-8 place-items-center rounded-md text-stone hover:bg-surface"><Icon name="ellipsis" size={18} /></DropdownMenu.Trigger><DropdownMenu.Content align="end">{#if canUpdate}<DropdownMenu.Item onSelect={() => goto(`/clinic/pets/${pet.id_mascotas}/edit`)}><Icon name="pencil" size={15} />{i18n.t('pets.edit')}</DropdownMenu.Item>{/if}{#if canDelete}<DropdownMenu.Item class="text-error" onSelect={() => { target = pet; deleteOpen = true; }}><Icon name="trash-2" size={15} />{i18n.t('pets.delete')}</DropdownMenu.Item>{/if}</DropdownMenu.Content></DropdownMenu.Root>{/if}</div></article>{/each}</div>
		{/if}
	</Card>
</section>

<ConfirmationDialog bind:open={deleteOpen} variant="danger" icon="trash-2" title={i18n.t('pets.deleteTitle')} description={i18n.t('pets.deleteDescription', { name: target?.nombre ?? '' })} confirmLabel={i18n.t('pets.delete')} cancelLabel={i18n.t('pets.cancel')} onConfirm={requestDelete}><form bind:this={deleteForm} method="POST" action="?/delete" use:enhance={remove}>{#if target}<input type="hidden" name="id" value={target.id_mascotas} />{/if}</form></ConfirmationDialog>
